            Embedding embedding = processImage(image, tokenizer);
            embeddings.add(embedding);
        }

        // Prepare batches for BERT layers
        List<LayerInput> layerInputs = prepareBatches(embeddings, model.batchSize);

        // Process through BERT layers
        List<LayerOutput> layerOutputs = new ArrayList<>();
        for (LayerInput input : layerInputs) {
            LayerOutput output = processThroughBERTLayers(input, model);
            layerOutputs.add(output);
        }

        // Predict using the last output
        List<Decision> predictions = new ArrayList<>();
