            Decision decision = predictClass(output, model);
            predictions.add(decision);
        }

        // Output predictions
        for (Decision prediction : predictions) {
            System.out.println("Prediction: " + prediction.getLabel() + " with probability " + prediction.getProbability());
        }
    }

    private static Embedding processImage(BufferedImage image, BOWTokenizer tokenizer) {
        // Tokenize the image (assuming an appropriate method exists)
        String[] tokenizedImage = tokenizer.tokenize(image);
        int[] tokenIds = new int[tokenizedImage.length];
        for (int i = 0; i < tokenizedImage.length; i++) {
            tokenIds[i] = tokenizer.getId(tokenizedImage[i]);
        }
        return new Embedding(tokenIds);
    }

    private static LayerInput prepareBatches(List<Embedding> embeddings, int batchSize) {
        List<LayerInput> inputs = new ArrayList<>();
        for (int i = 0; i < embeddings.size(); i += batchSize) {
            int end = Math.min(i + batchSize, embeddings.size());
            List<int[]> batch = new ArrayList<>();
            for (int j = i; j < end; j++) {
                batch.add(embeddings.get(j).getTokens());
            }
            inputs.add(new LayerInput(batch));
        }
        return inputs;
    }

    private static LayerOutput processThroughBERTLayers(LayerInput input, BERTModel model) {
        // PyTorch like BERT layers
        return model.getOutput(input);
    }

    private static Decision predictClass(LayerOutput output, BERTModel model) {
        double[] probs = model.predict(output);
        return new Decision(probs, Arrays.stream(probs).max().getAsDouble());
    }
}

class BERTModel {
    private BatchNeuralNetworkModel[] bertLayers;
