        for (int i = 0; i < bertLayers.length; i++) {
            input = bertLayers[i].process(input);
        }
        double[] output = new double[input.getSize()];
        for (int i = 0; i < input.getSize(); i++) {
            output[i] = input.get(i);
        }
        return new LayerOutput(projectionLayer, output);
    }

